120	/**
121	 * Composes the core system prompt from its constituent subsections.
122	 * Adheres to the minimal complexity principle by using simple interpolation of function calls.
123	 */
124	export function getCoreSystemPrompt(options: SystemPromptOptions): string {
125	  return `
126	${renderPreamble(options.preamble)}
127	
128	${renderCoreMandates(options.coreMandates)}
129	
130	${renderSubAgents(options.subAgents)}
131	
132	${renderAgentSkills(options.agentSkills)}
133	
134	${renderHookContext(options.hookContext)}
135	
136	${
137	  options.planningWorkflow
138	    ? renderPlanningWorkflow(options.planningWorkflow)
139	    : renderPrimaryWorkflows(options.primaryWorkflows)
140	}
141	
142	${options.taskTracker ? renderTaskTracker() : ''}
143	
144	${renderOperationalGuidelines(options.operationalGuidelines)}
145	
146	${renderInteractiveYoloMode(options.interactiveYoloMode)}
147	
148	${renderSandbox(options.sandbox)}
149	
150	${renderGitRepo(options.gitRepo)}
151	`.trim();
152	}
